def retry_delay(headers: dict[str, object], default_seconds: int = 5) -> int:
    # The canonical spelling 'Retry-After' takes precedence.
    # If 'Retry-After' is present, it is used even if it's invalid (parse_retry_after returns None).
    # If 'Retry-After' is not present, 'retry-after' is checked.

    val = None
    if "Retry-After" in headers:
        val = parse_retry_after(headers["Retry-After"])
    elif "retry-after" in headers:
        val = parse_retry_after(headers["retry-after"])

    if val is not None:
        return val

    return default_seconds

